CREATE TABLE public.hr_departments (tenant_id uuid NOT NULL REFERENCES public.tenants(id),record_key text NOT NULL,sort_position integer NOT NULL DEFAULT 0,name text,parent_department text,description text,status text,metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,record_key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.hr_departments TO authenticated; GRANT ALL ON public.hr_departments TO service_role;
ALTER TABLE public.hr_departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY hr_departments_read ON public.hr_departments FOR SELECT TO authenticated USING(coalesce(private.has_module_access(tenant_id,'hr','view'),false));
CREATE POLICY hr_departments_write ON public.hr_departments FOR ALL TO authenticated USING(coalesce(private.has_module_access(tenant_id,'hr','edit'),false)) WITH CHECK(coalesce(private.has_module_access(tenant_id,'hr','edit'),false));
INSERT INTO public.hr_departments(tenant_id,record_key,sort_position,name,parent_department,description,status,metadata) SELECT tenant_id,record_key,position,data->>'name',data->>'parentDepartment',data->>'description',data->>'status',data-ARRAY['name','parentDepartment','description','status'] FROM public.tenant_collection_records WHERE collection='departments' ON CONFLICT DO NOTHING;
CREATE TABLE public.hr_leave_requests (tenant_id uuid NOT NULL REFERENCES public.tenants(id),record_key text NOT NULL,sort_position integer NOT NULL DEFAULT 0,employee_id text,employee_name text,department text,type text,from_date text,to_date text,days numeric,approver text,status text,metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,record_key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.hr_leave_requests TO authenticated; GRANT ALL ON public.hr_leave_requests TO service_role;
ALTER TABLE public.hr_leave_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY hr_leave_requests_read ON public.hr_leave_requests FOR SELECT TO authenticated USING(coalesce(private.has_module_access(tenant_id,'hr','view'),false));
CREATE POLICY hr_leave_requests_write ON public.hr_leave_requests FOR ALL TO authenticated USING(coalesce(private.has_module_access(tenant_id,'hr','edit'),false)) WITH CHECK(coalesce(private.has_module_access(tenant_id,'hr','edit'),false));
INSERT INTO public.hr_leave_requests(tenant_id,record_key,sort_position,employee_id,employee_name,department,type,from_date,to_date,days,approver,status,metadata) SELECT tenant_id,record_key,position,data->>'employeeId',data->>'employeeName',data->>'department',data->>'type',data->>'from',data->>'to',nullif(data->>'days','')::numeric,data->>'approver',data->>'status',data-ARRAY['employeeId','employeeName','department','type','from','to','days','approver','status'] FROM public.tenant_collection_records WHERE collection='leaveRequests' ON CONFLICT DO NOTHING;
