CREATE POLICY hr_vacancies_write ON public.hr_vacancies FOR ALL TO authenticated USING(coalesce(private.has_module_access(tenant_id,'hr','edit'),false)) WITH CHECK(coalesce(private.has_module_access(tenant_id,'hr','edit'),false));
INSERT INTO public.hr_vacancies(tenant_id,record_key,sort_position,role,department,candidates,stage,owner,target_date,status,metadata) SELECT tenant_id,record_key,position,data->>'role',data->>'department',nullif(data->>'candidates','')::numeric,data->>'stage',data->>'owner',data->>'targetDate',data->>'status',data-ARRAY['role','department','candidates','stage','owner','targetDate','status'] FROM public.tenant_collection_records WHERE collection='vacancies' ON CONFLICT DO NOTHING;
