INSERT INTO public.finance_account_records(tenant_id,record_key,sort_position,name,code,type,currency,opening_balance,status,metadata) SELECT tenant_id,record_key,position,data->>'name',data->>'code',data->>'type',data->>'currency',nullif(data->>'openingBalance','')::numeric,data->>'status',data-ARRAY['name','code','type','currency','openingBalance','status'] FROM public.tenant_collection_records WHERE collection='financeAccounts' ON CONFLICT DO NOTHING;
CREATE TABLE public.finance_credit_records (tenant_id uuid NOT NULL REFERENCES public.tenants(id),record_key text NOT NULL,sort_position integer NOT NULL DEFAULT 0,customer text,contract_id text,order_id text,total numeric,initial_payment numeric,balance numeric,months numeric,status text,metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,record_key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_credit_records TO authenticated; GRANT ALL ON public.finance_credit_records TO service_role;
ALTER TABLE public.finance_credit_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_credit_records_read ON public.finance_credit_records FOR SELECT TO authenticated USING(coalesce(private.has_module_access(tenant_id,'credits','view'),false));
CREATE POLICY finance_credit_records_write ON public.finance_credit_records FOR ALL TO authenticated USING(coalesce(private.has_module_access(tenant_id,'credits','edit'),false)) WITH CHECK(coalesce(private.has_module_access(tenant_id,'credits','edit'),false));
INSERT INTO public.finance_credit_records(tenant_id,record_key,sort_position,customer,contract_id,order_id,total,initial_payment,balance,months,status,metadata) SELECT tenant_id,record_key,position,data->>'customer',data->>'contractId',data->>'orderId',nullif(data->>'total','')::numeric,nullif(data->>'initialPayment','')::numeric,nullif(data->>'balance','')::numeric,nullif(data->>'months','')::numeric,data->>'status',data-ARRAY['customer','contractId','orderId','total','initialPayment','balance','months','status'] FROM public.tenant_collection_records WHERE collection='credits' ON CONFLICT DO NOTHING;
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS record_key text, ADD COLUMN IF NOT EXISTS sort_position integer DEFAULT 0, ADD COLUMN IF NOT EXISTS metadata jsonb DEFAULT '{}';
CREATE UNIQUE INDEX IF NOT EXISTS employees_record_key ON public.employees(tenant_id,record_key);
UPDATE public.employees SET record_key=id::text WHERE record_key IS NULL;
INSERT INTO public.employees(tenant_id,record_key,sort_position,full_name,position,department,email,phone,salary,status,metadata)
SELECT tenant_id,record_key,position,coalesce(data->>'name',''),data->>'position',data->>'department',data->>'email',data->>'phone',coalesce(nullif(data->>'salary','')::numeric,0),'active',data-ARRAY['name','position','department','email','phone','salary']
FROM public.tenant_collection_records WHERE collection='employees' ON CONFLICT(tenant_id,record_key) DO NOTHING;
COMMENT ON TABLE public.tenant_collection_records IS 'DEPRECATED: replaced by employees, hr_departments, hr_leave_requests, hr_vacancies, business_contracts and dedicated finance record tables. Retained for migration audit only; never read or written by the app.';